@RestControllerAdvice
public class ApiExceptionAdvice {

    @ResponseStatus(HttpStatus.BAD_REQUEST)
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ErrorResult validation(MethodArgumentNotValidException e) {
        List<FieldError> errors = e.getBindingResult().getFieldErrors().stream()
                .map(f -> new FieldError(f.getField(), f.getDefaultMessage()))
                .toList();
        return new ErrorResult("VALIDATION", "입력값이 올바르지 않습니다", errors);
    }

    @ResponseStatus(HttpStatus.NOT_FOUND)
    @ExceptionHandler(NoSuchElementException.class)
    public ErrorResult notFound(NoSuchElementException e) {
        return new ErrorResult("NOT_FOUND", "대상을 찾을 수 없습니다", null);
    }

    @ResponseStatus(HttpStatus.BAD_REQUEST)
    @ExceptionHandler(NotEnoughStockException.class)
    public ErrorResult stock(NotEnoughStockException e) {
        return new ErrorResult("NOT_ENOUGH_STOCK", e.getMessage(), null);
    }

    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    @ExceptionHandler(Exception.class)
    public ErrorResult unexpected(Exception e) {
        log.error("unexpected", e);
        return new ErrorResult("INTERNAL", "서버 오류가 발생했습니다", null);
    }
}
